import"./chunks/assets.DeKsZZ4W.js";import{E as e,at as t,it as n,vt as r}from"./chunks/framework.DwjJr7zi.js";var i=JSON.parse(`{"title":"节点测活(完善版)","description":"","frontmatter":{"title":"节点测活(完善版)"},"headers":[],"relativePath":"blog/posts/1210.md","filePath":"blog/posts/1210.md","lastUpdated":1783382106000}`),a={name:`blog/posts/1210.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="节点测活-完善版" tabindex="-1">节点测活(完善版) <a class="header-anchor" href="#节点测活-完善版" aria-label="Permalink to “节点测活(完善版)”">​</a></h1><div class="telegram-content"><u>Sub-Store 的节点测活脚本(完善版)</u><br><br>支持以下环境: <br><br>1. Loon 和 Surge<br><br>2. Node.js 版(需要 <code>HTTP META</code> 配合)<br><br><a href="https://github.com/xream/http-meta">HTTP META 本体</a><br><br>Android 也可本地使用 配合<a href="/blog/posts/1008"> Android 本地版 Sub-Store</a><br><br>▎使用<br><br>🌝 参数一般不用加 这里仅做一个示范<br><br>具体说明可查看脚本内容<br><br>常用参数 <code>timeout</code> 可适当调小, <code>keep_incompatible</code> 保留当前客户端不兼容的协议, <code>show_latency</code> 节点名称加上延迟<br><br><code>url</code> 需要 encodeURIComponent. 默认 <code>http://connectivitycheck.platform.hicloud.com/generate_204</code><br><code>status</code> 合法的状态码的表达式. 需要 encodeURIComponent . 默认 <code>204</code><br><br>举例, 如需使用 <code>http://223.6.6.6</code> 状态码 <code>404</code>: <code>url=http%3A%2F%2F223.6.6.6&amp;status=404</code><br><br>在 <code>节点操作</code> -<code> 脚本操作</code> 中 选择 <code>链接</code><br><br>然后按需填入链接内容<br><br>1. Loon 和 Surge:<br><br><code>https://raw.githubusercontent.com/xream/scripts/main/surge/modules/sub-store-scripts/check/availability.js#show_latency=true&amp;keep_incompatible=true&amp;status=204&amp;url=http%3A%2F%2Fconnectivitycheck.platform.hicloud.com%2Fgenerate_204&amp;timeout=1000&amp;retries=1&amp;retry_delay=1000&amp;concurrency=10<br><br></code>2. Node.js 版(需要 <a href="https://github.com/xream/http-meta">HTTP META</a> 配合):<br><br><code>https://raw.githubusercontent.com/xream/scripts/main/surge/modules/sub-store-scripts/check/http_meta_availability.js#show_latency=true&amp;keep_incompatible=true&amp;status=204&amp;url=http%3A%2F%2Fconnectivitycheck.platform.hicloud.com%2Fgenerate_204&amp;timeout=1000&amp;retries=1&amp;retry_delay=1000&amp;concurrency=10&amp;http_meta_protocol=http&amp;http_meta_host=127.0.0.1&amp;http_meta_port=9876&amp;http_meta_start_delay=3000&amp;http_meta_proxy_timeout=10000</code><br><br><img class="telegram-custom-emoji" src="/telegram/AgAEDgACMozQVw.webp" alt="🤭" loading="lazy" decoding="async"> <a href="/blog/214/">Sub-Store 合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADRw4AApYl0Vc.webp" alt="🧐" loading="lazy" decoding="async"> <a href="/blog/">频道资源合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADmw4AArTV0Fc.webp" alt="😄" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha/957">恰饭推荐</a> <img class="telegram-custom-emoji" src="/telegram/AgAD3A4AAjTykVM.webp" alt="💬" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha_group">群组</a><br><br><img class="telegram-custom-emoji" src="/telegram/AgAD_A0AAh_-0Fc.webp" alt="🥰" loading="lazy" decoding="async"> #Sub-Store #SubStore #脚本 #节点 #订阅 #测活 #节点测活 #节点延迟 #延迟 #检测 #check #HTTP-META #HTTPMETA #Meta #Clash #脚本 #Node #服务器 #VPS</div><p class="telegram-source"><a href="https://t.me/zhetengsha/1210">查看 Telegram 原文</a></p>`,3)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};